+/// One Montgomery round: adds `k * n` with `k = r0 * -n^-1 mod 2^64` to the
+/// words `r0..r4` plus `carry_in` at `r4`, returning the shifted words
+/// `r1..r4` and the carry out of `r4`.
+#[inline(always)]
+fn reduce_step(r0: u64, r1: u64, r2: u64, r3: u64, r4: u64, carry_in: u64) -> ([u64; 4], u64) {
+    let k = r0.wrapping_mul(MODULUS_INV);
+    // r0 + lo(k * n0) is 0 mod 2^64, so it carries exactly when r0 != 0.
+    let carry = mul_hi(k, MODULUS[0]) + u64::from(r0 != 0);
+    let (r1, carry) = mac(r1, k, MODULUS[1], carry);
+
+    // n2 + n3 * 2^64 = 2^128 - 2^96 + 2^64 - 1, so its product with k is
+    // (k * 2^128 + k * 2^64) - (k * 2^96 + k), which fits in three words.
+    let (h0, borrow) = sbb(0, k, 0);
+    let (h1, borrow) = sbb(k, k << 32, borrow);
+    let h2 = k - (k >> 32) - borrow;
+
+    let (r2, carry) = adc(r2, h0, carry);
+    let (r3, carry) = adc(r3, h1, carry);
+    let sum = (r4 as u128) + (h2 as u128) + (carry as u128) + (carry_in as u128);
+
+    ([r1, r2, r3, sum as u64], (sum >> 64) as u64)
+}

